const bcrypt = require('/usr/src/node-red/node_modules/bcryptjs');
if (!process.env.SELFHOST_ADMIN_PASSWORD || !process.env.SELFHOST_CREDENTIAL_SECRET) throw new Error('Administrator and flow encryption credentials are required');
module.exports = {
  uiPort: 1880, uiHost: '0.0.0.0', userDir: '/data', flowFile: 'flows.json',
  credentialSecret: process.env.SELFHOST_CREDENTIAL_SECRET,
  adminAuth: {type:'credentials', users:[{username:process.env.SELFHOST_ADMIN_USER || 'admin', password:bcrypt.hashSync(process.env.SELFHOST_ADMIN_PASSWORD,12), permissions:'*'}]},
  httpNodeRoot: process.env.SELFHOST_HTTP_NODE_ROOT || '/api',
  disableEditor: process.env.SELFHOST_DISABLE_EDITOR === 'true',
  contextStorage: { default: { module: 'localfilesystem' } },
  logging: { console: { level: process.env.SELFHOST_LOG_LEVEL || 'info', metrics:false, audit:true } },
  editorTheme: { projects: { enabled: process.env.NODE_RED_ENABLE_PROJECTS === 'true' } }
};
